def planner_around_window(spans,index_value,before_count,after_count):
    start=max(0,index_value-before_count)
    stop=min(len(spans)-1,index_value+after_count)
    out=[]
    i=start
    while i<=stop:
        out.append(spans[i].get('id'))
        i+=1
    return out

